const ctx = $('When Executed by Another Workflow').first().json;
const rows = (name) => $(name).all().map(i => i.json).filter(r => r && r.id !== undefined && r.id !== null);

const horizon = Number(ctx.horizon_days) || 30;
const SAFETY_BUFFER = 4000000;
const NORMAL_PRICE = 1250;

// 1. Opening cash (Day 0 row, else the lowest forecast_day, newest first)
const cash = rows('Get Cash Position');
if (!cash.length) throw new Error('No cash position found for ' + ctx.company_id);
cash.sort((a, b) => Number(a.forecast_day) - Number(b.forecast_day) || Number(b.id) - Number(a.id));
const startingCash = Number(cash[0].balance);

// 2. Latest diesel price (newest fuel_price_events row, else the normal price)
const fuelRows = rows('Get Latest Fuel Price').sort((a, b) => Number(b.id) - Number(a.id));
const latestFuel = fuelRows[0] || null;
const fuelPrice = latestFuel ? Number(latestFuel.new_price) : NORMAL_PRICE;
const currentDay = Number(ctx.current_day ?? (latestFuel ? latestFuel.event_day : 0) ?? 0) || 0;

// 3. Money in and money out
const isOpen = (s) => String(s || '').toLowerCase() === 'open';
const isSettled = (s) => ['paid', 'cancelled', 'canceled', 'closed', 'settled'].includes(String(s || '').toLowerCase());

const receivables = rows('Get Receivables').filter((r) => isOpen(r.status));
const bills = [
  ...rows('Get Payables').filter((r) => !isSettled(r.status)).map((r) => ({ ...r, kind: 'payable' })),
  ...rows('Get Commitments').filter((r) => !isSettled(r.status)).map((r) => ({ ...r, kind: 'commitment' }))
];
const isDiesel = (b) => b.kind === 'payable' &&
  (/diesel|fuel/i.test(String(b.item_name)) || (b.amount === null && b.quantity !== null));
const billAmount = (b) => isDiesel(b) ? Number(b.quantity ?? 2880) * fuelPrice : Number(b.amount);

// 4. Loop through every day of the horizon
let balance = startingCash;
let minimumProjectedBalance = startingCash;
let dayOfMinimum = 0;
let breachDay = null;
let expectedInflows = 0;
let expectedOutflows = 0;
const dailyForecast = [];

for (let day = 0; day <= horizon; day++) {
  let inflows = 0;
  let outflows = 0;
  const events = [];

  for (const inv of receivables) {
    if (Number(inv.due_day) === day) {
      inflows += Number(inv.amount);
      events.push({ type: 'INFLOW', name: inv.invoice_id, client: inv.client_name, amount: Number(inv.amount) });
    }
  }
  for (const b of bills) {
    if (Number(b.due_day) === day) {
      const amt = billAmount(b);
      outflows += amt;
      events.push({ type: 'OUTFLOW', name: b.item_name, amount: amt });
    }
  }

  balance = balance + inflows - outflows;
  expectedInflows += inflows;
  expectedOutflows += outflows;

  if (balance < minimumProjectedBalance) {
    minimumProjectedBalance = balance;
    dayOfMinimum = day;
  }
  if (day > 0 && breachDay === null && balance < SAFETY_BUFFER) {
    breachDay = day;
  }
  dailyForecast.push({ day, inflows, outflows, balance, events });
}

const runId = ctx.run_id || ('W03-' + Date.now());

return [{
  json: {
    forecast_run_id: 'FC-' + runId,
    run_id: runId,
    company_id: ctx.company_id,
    horizon_days: horizon,
    current_cash: startingCash,
    expected_inflows: expectedInflows,
    expected_outflows: expectedOutflows,
    minimum_projected_balance: minimumProjectedBalance,
    day_of_minimum: dayOfMinimum,
    breach_day: breachDay,
    days_to_breach: breachDay === null ? null : Math.max(0, breachDay - currentDay),
    safety_buffer: SAFETY_BUFFER,
    fuel_price: fuelPrice,
    fuel_price_used: fuelPrice,
    open_invoices: receivables.map((r) => ({
      invoice_id: r.invoice_id, client_name: r.client_name, amount: Number(r.amount), due_day: Number(r.due_day)
    })),
    daily_forecast: dailyForecast
  }
}];

const f = $('Build Forecast').first().json;
return [{ json: {
  forecast_run_id: f.forecast_run_id,
  run_id: f.run_id,
  company_id: f.company_id,
  horizon_days: f.horizon_days,
  current_cash: f.current_cash,
  expected_inflows: f.expected_inflows,
  expected_outflows: f.expected_outflows,
  minimum_projected_balance: f.minimum_projected_balance,
  day_of_minimum: f.day_of_minimum,
  days_to_breach: f.days_to_breach
} }];
